contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 v1, uint256 v2, int256 i1, int256 i2,
                 address asset, uint256 amount, uint256 unlockTime, bool burnable) public {
        // Before configuration ends the contract is still configurable.
        bool cfgBefore = c.configured();

        // Enforcement is off for this contract (msg.sender of c's calls).
        c.setEnforcement(false);

        // With enforcement off, enforceTolerance must never revert for any uint values.
        bool okU;
        try c.enforceTolerance(v1, v2) { okU = true; } catch { okU = false; }

        // With enforcement off, enforceToleranceInt must never revert for any int values.
        bool okI;
        try c.enforceToleranceInt(i1, i2) { okI = true; } catch { okI = false; }

        // End configuration: this must flip the public configured() flag to true.
        c.endConfiguration();
        bool cfgAfter = c.configured();

        // After configuration, a non-successful-proposal caller must not be able
        // to reconfigure flash governance: configureFlashGovernance must revert.
        bool cfgReverted;
        try c.configureFlashGovernance(asset, amount, unlockTime, burnable) { cfgReverted = false; }
        catch { cfgReverted = true; }

        // Enforcement is still off, so tolerance checks still never revert.
        bool okU2;
        try c.enforceTolerance(v1, v2) { okU2 = true; } catch { okU2 = false; }
        bool okI2;
        try c.enforceToleranceInt(i1, i2) { okI2 = true; } catch { okI2 = false; }

        assert(!cfgBefore && cfgAfter && cfgReverted && okU && okI && okU2 && okI2);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 v1, uint256 v2, int256 i1, int256 i2) public {
        // Fresh contract: enforcement for this caller is off by default, so the
        // tolerance checks short-circuit and must not revert for any values.
        bool okU0;
        try c.enforceTolerance(v1, v2) { okU0 = true; } catch { okU0 = false; }

        // Turn enforcement on: since this caller is not a Configurable contract,
        // enforceTolerance must revert for any values.
        c.setEnforcement(true);
        bool rU1;
        try c.enforceTolerance(v1, v2) { rU1 = false; } catch { rU1 = true; }

        bool rI1;
        try c.enforceToleranceInt(i1, i2) { rI1 = false; } catch { rI1 = true; }

        // Turn enforcement back off: tolerance checks must again never revert
        // for any values, for both the uint and int variants.
        c.setEnforcement(false);
        bool okU2;
        try c.enforceTolerance(v1, v2) { okU2 = true; } catch { okU2 = false; }

        bool okI2;
        try c.enforceToleranceInt(i1, i2) { okI2 = true; } catch { okI2 = false; }

        assert(okU0 && rU1 && rI1 && okU2 && okI2);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address asset, uint256 amount, uint256 unlockTime, bool burnable, address dao2) public {
        require(asset != address(0) && amount > 0 && dao2 != address(0));

        // On a fresh (unconfigured) contract, anyone may configure flash governance.
        c.configureFlashGovernance(asset, amount, unlockTime, burnable);

        (address a, uint256 am, uint256 ut, bool ab) = c.flashGovernanceConfig();

        // End configuration: after this, governance params are locked.
        c.endConfiguration();
        bool cfg = c.configured();

        // setDAO by a non-DAO, non-zero address must now revert since configured.
        bool setDAOReverted;
        try c.setDAO(dao2) { setDAOReverted = false; } catch { setDAOReverted = true; }

        // DAO must remain the original DAO address (constructor argument), not dao2.
        address currentDAO = c.DAO();

        assert(a == asset && am == amount && ut == unlockTime && ab == burnable && cfg && setDAOReverted && currentDAO != dao2);
    }

    receive() external payable {}
}

