    constructor(C _c) { c = _c; }
    function run(address a1, address a2, bool f1, bool f2) public payable {
        // length mismatch must revert (fresh c, configured == false so proposal check passes)
        address[] memory gs = new address[](2);
        gs[0] = a1;
        gs[1] = a2;
        bool[] memory fs = new bool[](1);
        fs[0] = f1;
        bool mismatchReverted;
        try c.setGoverned(gs, fs) { mismatchReverted = false; } catch { mismatchReverted = true; }

        // matching lengths must succeed and update the mapping for every entry
        bool[] memory fs2 = new bool[](2);
        fs2[0] = f1;
        fs2[1] = f2;
        bool ok;
        try c.setGoverned(gs, fs2) { ok = true; } catch { ok = false; }

        bool g1 = c.governed(a1);
        bool g2 = c.governed(a2);
        assert(mismatchReverted && ok && g1 == f1 && g2 == f2);
    }
    receive() external payable {}
}

