contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address a1, address a2, bool f) public {
        // mismatched lengths -> must revert
        address[] memory g1 = new address[](1);
        g1[0] = a1;
        bool[] memory b1 = new bool[](2);
        b1[0] = f;
        b1[1] = f;
        bool reverted;
        try c.setGoverned(g1, b1) { reverted = false; } catch { reverted = true; }

        // equal lengths -> must succeed and update the mapping
        address[] memory g2 = new address[](2);
        g2[0] = a1;
        g2[1] = a2;
        bool[] memory b2 = new bool[](2);
        b2[0] = f;
        b2[1] = !f;
        c.setGoverned(g2, b2);

        assert(reverted && c.governed(a1) == f && c.governed(a2) == !f);
    }
    receive() external payable {}
}

