contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Make this test contract look 'configured' so enforceTolerance's
    // Configurable(msg.sender).configured() check passes.
    fallback() external payable {
        assembly {
            mstore(0, 1)
            return(0, 32)
        }
    }

    function run(uint256 v) public {
        require(v > 0 && v <= type(uint256).max / 2);

        // Fresh deployment: Governable.configured is false, so onlySuccessfulProposal passes.
        c.configureSecurityParameters(1, 1000, 50);
        c.setEnforcement(true);

        bool revertedEqual;
        try c.enforceTolerance(v, v) {
            revertedEqual = false;
        } catch {
            revertedEqual = true;
        }

        bool revertedDouble;
        try c.enforceTolerance(2 * v, v) {
            revertedDouble = false;
        } catch {
            revertedDouble = true;
        }

        // With changeTolerance = 50 and active enforcement, a zero-percent
        // change is always allowed while a 100% change is always rejected.
        assert(!revertedEqual && revertedDouble);
    }

    receive() external payable {}
}

