            bigChange = ((hi - lo) * 100) >= uint256(1) * 100 / 100 * uint256(1);
            bigChange = ((hi - lo) * 100) >= uint256(tolerance) * hi;
        }

        assert(!revertedOff && (bigChange ? revertedOn : true));
    }
    receive() external payable {}
}

